	@Test
	public void allPairsPlusSeedsFromAdjacencyKeyEnumeration() throws Exception {
		long[][] edges = {
				{ 10L, 20L }, { 10L, 30L }, { 20L, 40L }, { 30L, 50L }
		};
		long[] keys = { 10L, 20L, 30L };
		int[] runStart = { 0, 2, 3, 4 };
		NativeLmdbQuerySource.NativeAdjacency adjacency = new NativeLmdbQuerySource.NativeAdjacency() {
			@Override
			public long find(long key) {
				return key == 10L ? 1L : key == 20L ? 2L : key == 30L ? 3L : NOT_FOUND;
			}

			@Override
			public long size(long runHandle) {
				int dense = (int) runHandle - 1;
				return runStart[dense + 1] - runStart[dense];
			}

			@Override
			public long neighborAt(long runHandle, long runOffset) {
				int dense = (int) runHandle - 1;
				return edges[runStart[dense] + (int) runOffset][1];
			}

			@Override
			public long contextAt(long runHandle, long runOffset) {
				return 0L;
			}

			@Override
			public boolean supportsKeyEnumeration() {
				return true;
			}

			@Override
			public long keyCount() {
				return keys.length;
			}

			@Override
			public long keyAt(long keyOrdinal) {
				return keys[(int) keyOrdinal];
			}
		};
		PathGraphSource source = new PathGraphSource(edges, adjacency);
		SingletonSet telemetry = new SingletonSet();
		telemetry.setRuntimeTelemetryEnabled(true);
		NativeSlotLayout layout = new NativeSlotLayout(Map.of("start", 0, "target", 1), null);
		layout.freeze(List.of("start", "target"));
		RowState row = new RowState(source, layout, new QueryBindingSet(), telemetry);
		Arrays.fill(row.slots, NativeLmdbQuerySource.UNKNOWN_ID);
		row.recomputeBoundMask();
		PatternPlan step = new PatternPlan(Term.slot(0), Term.constant(PathGraphSource.PREDICATE), Term.slot(1),
				Term.unbound(), ContextConstraint.UNRESTRICTED, false, edges.length);
		PathPlan path = new PathPlan(step, 0, NativeLmdbQuerySource.UNKNOWN_ID, 1,
				NativeLmdbQuerySource.UNKNOWN_ID, TripleIndex.SUBJ_IDX, TripleIndex.OBJ_IDX, false);

		int rows = 0;
		String previous = System.getProperty(PATH_ADJACENCY_SEEDS_ENABLED);
		try {
			System.setProperty(PATH_ADJACENCY_SEEDS_ENABLED, "true");
			try (RowCursor cursor = path.open(row)) {
				while (cursor.next()) {
					rows++;
				}
			}
		} finally {
			restoreProperty(PATH_ADJACENCY_SEEDS_ENABLED, previous);
		}

		assertThat(rows).isEqualTo(6);
		assertThat(source.unboundRowsRead)
				.as("an exact adjacency key domain must replace the LMDB predicate seed scan")
				.hasValue(0);
		assertThat(source.pathStepCalls)
				.as("the same adjacency view must serve every subsequent frontier expansion")
				.hasValue(0);
		assertThat(telemetry.getLongMetricActual("nativePathAdjacencySeedKeysActual")).isEqualTo(3L);
	}

	@Test
	public void boundExistenceUsesBidirectionalAdjacencySearch() throws Exception {
		IRI root;
		IRI target = null;
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI edge = vf.createIRI(EX, "treeEdge");
			root = vf.createIRI(EX, "treeRoot");
			List<IRI> level = List.of(root);
			long nextId = 0L;
			conn.begin();
			for (int depth = 0; depth < 4; depth++) {
				List<IRI> next = new ArrayList<>(level.size() * 4);
				for (int parentIndex = 0; parentIndex < level.size(); parentIndex++) {
					IRI parent = level.get(parentIndex);
					for (int childIndex = 0; childIndex < 4; childIndex++) {
						boolean last = depth == 3 && parentIndex == level.size() - 1 && childIndex == 3;
						IRI child = vf.createIRI(EX, last ? "treeTarget" : "treeNode" + nextId++);
						conn.add(parent, edge, child);
						next.add(child);
						if (last) {
							target = child;
						}
					}
				}
				level = next;
			}
			conn.commit();
		}
		assertThat(target).isNotNull();
		assertThat(((LmdbStore) repository.getSail()).awaitDirectAdjacencyReady(60, TimeUnit.SECONDS)).isTrue();
		String query = q("SELECT * WHERE { <" + root + "> ex:treeEdge+ <" + target + "> . }");

		List<String> expected = genericRows(query);
		List<String> actual = withProperty(PATH_BIDIRECTIONAL_ENABLED, "true", () -> rows(query));
		String rendered = withProperty(PATH_BIDIRECTIONAL_ENABLED, "true", () -> telemetry(query));

		assertThat(actual).containsExactlyElementsOf(expected).hasSize(1);
		assertThat(rendered)
				.contains("nativePathBidirectionalSearchesActual=1")
				.contains("nativePathBidirectionalForwardExpansionsActual=")
				.contains("nativePathBidirectionalBackwardExpansionsActual=")
				.contains("reason: PATH_BIDIRECTIONAL_FORWARD_ADJACENCY[step=0,direction=subject-to-object]")
				.contains("reason: PATH_BIDIRECTIONAL_BACKWARD_ADJACENCY[step=0,direction=object-to-subject]");
	}

